import {test, expect} from '@playwright/test';
import {createHash} from 'node:crypto';
import {recognitionFixture} from '../fixtures/recognition.mjs';

// Generated bytes and deferred same-origin HTTP replies only. No recording,
// camera, model, backup, or analysis operation is started by these cases.
const bytes = Buffer.from('generated review-intent source');
const sha = createHash('sha256').update(bytes).digest('hex');
const id = 'a'.repeat(32), newerId = 'b'.repeat(32);
const upload = value => ({name:'generated-review.json', mimeType:'application/json', buffer:Buffer.from(JSON.stringify(value))});
function result(camera) {
  const value = recognitionFixture(sha);
  value.receipt.camera = value.trace.camera = camera;
  value.receipt.events.forEach(event => {event.camera = camera;});
  return value;
}
const item = itemId => ({id:itemId, state:'completed', name:'generated.webm', source:'generated', sha256:sha,
  bytes:bytes.length, created_at:1000, copied_at:1000, observations:1, analysis_eligible:true});
const task = {segment:/^Record a LAN camera/, backup:/^Use my existing DVR/, analysis:/^Analyze a recording/};
const region = {segment:'LAN camera recorder', backup:'Existing DVR backup', analysis:'Local recording analysis'};
const open = {segment:'Review segment', backup:'Review backup', analysis:'Open results'};
const connect = {segment:'Connect LAN recorder', backup:'Connect to this computer', analysis:'Connect local analysis'};
const nav = (page, name) => page.getByRole('navigation',{name:'Main navigation'}).getByRole('button',{name:new RegExp('^'+name)});

async function setup(page, older) {
  const state = {held:null, writes:[], newerSources:0};
  const oldPrefix = older === 'analysis' ? `/api/analysis/jobs/${id}`
    : older === 'backup' ? `/api/library/items/${id}` : `/api/recorder/segments/${id}`;
  const catalog = {token:'generated-review-token', ready:true, recordings:[], recorder_active:false,
    models:[{id:'model', name:'Generated model'}], rules:[{id:'rules', name:'Generated rules', models:['model'], summary:[]}],
    job:{id, state:'completed', phase:'completed', recording:'generated.webm', frames_read:6, frames_analyzed:2, max_frames:6000, elapsed_seconds:1}};
  await page.route('**/api/**', route => {
    const request = route.request(), path = new URL(request.url()).pathname;
    if (request.method() === 'POST') state.writes.push(path);
    if (path.endsWith('/session')) return route.fulfill({json:catalog});
    if (path === '/api/setup/cameras') return route.fulfill({json:{enabled:true, sources:[]}});
    if (path === '/api/library/status') return route.fulfill({json:{configured:true, active:false, analyzing:false,
      state:'paused', error:null, config:{source_folder:'/generated/source', backup_folder:'/generated/backup',
        max_storage_gib:100, reserve_gib:2, settle_seconds:60, recursive:true}, storage_bytes:bytes.length,
      disk_free_bytes:1024**3, waiting:0, scan_limited:false, unsupported:[], items:[item(id)], counters:{copied:1, duplicates:0}}});
    if (path === '/api/recorder/status') return route.fulfill({json:{state:'stopped', active:false, name:'Generated recorder',
      limits:{segment_seconds:30, retention_minutes:60, max_segments:120, max_storage_mib:2048},
      counters:{recorded:2, analyzed:2, dropped:0, expired:0, reconnects:0}, segments:[item(older === 'segment' ? id : newerId)],
      queue_depth:0, oldest_pending_seconds:0, storage_bytes:bytes.length, disk_free_bytes:1024**3, worker:{}, retry_seconds:0,
      seconds_since_completed_segment:null}});
    if (path === `${oldPrefix}/source`) {state.held = route; return;}
    if (path.endsWith('/result')) return route.fulfill({json:result(path.includes(newerId) ? 'newer-segment-review' : 'older-download')});
    if (path.endsWith('/source')) {state.newerSources++; return route.fulfill({contentType:'video/webm', body:bytes});}
    return route.fulfill({status:503, json:{error:{message:'Unused generated endpoint.'}}});
  });
  await page.goto('/#recognition');
  await page.getByRole('button',{name:/^Open saved results/}).click();
  await page.getByLabel('Open recognition results').setInputFiles(upload(result('retained-review')));
  await expect(page.locator('.recognition-facts')).toContainText('retained-review');
  await page.getByRole('button',{name:task[older]}).click();
  const panel = page.getByRole('region',{name:region[older]});
  await panel.getByRole('button',{name:connect[older], exact:true}).click();
  if (older === 'backup') await panel.locator('.backup-saved summary').click();
  await panel.getByRole('button',{name:open[older], exact:true}).click();
  await expect.poll(() => Boolean(state.held)).toBe(true);
  return {state, panel};
}

for (const newer of ['valid results', 'rejected results', 'source match']) test(`a late segment review preserves newer ${newer} intent`, async ({page}) => {
  const {state, panel} = await setup(page, 'segment');
  await page.getByRole('button',{name:/^Open saved results/}).click();
  if (newer === 'source match') {
    await page.getByLabel('Match original recording').setInputFiles({name:'generated.webm', mimeType:'video/webm', buffer:bytes});
    await expect(page.locator('.recognition-facts')).toContainText('recording fingerprint matched');
  } else {
    await page.getByLabel('Open recognition results').setInputFiles(newer === 'valid results' ? upload(result('newer-imported-review'))
      : {name:'rejected.json', mimeType:'application/json', buffer:Buffer.from('{}')});
    if (newer === 'valid results') await expect(page.locator('.recognition-facts')).toContainText('newer-imported-review');
    else await expect(page.locator('.recognition-error[role="alert"]')).toBeVisible();
  }
  await state.held.fulfill({contentType:'video/webm', body:bytes});
  await page.getByRole('button',{name:task.segment}).click();
  await expect(panel.getByText('A newer review was requested.',{exact:false})).toBeVisible();
  await expect(page.locator('.recognition-facts')).toContainText(newer === 'valid results' ? 'newer-imported-review' : 'retained-review');
  if (newer === 'source match') await expect(page.locator('.recognition-facts')).toContainText('recording fingerprint matched');
  await expect(panel.locator('.lan-segment.unhandled')).toHaveCount(1);
  expect(state.writes).toEqual([]);
});

for (const older of ['backup', 'analysis']) test(`a late ${older} download cannot replace a newer segment review`, async ({page}) => {
  const {state, panel} = await setup(page, older);
  await page.getByRole('button',{name:task.segment}).click();
  const recorder = page.getByRole('region',{name:region.segment});
  await recorder.getByRole('button',{name:connect.segment, exact:true}).click();
  await recorder.getByRole('button',{name:open.segment, exact:true}).click();
  await expect(page.locator('.recognition-facts')).toContainText('newer-segment-review');
  await state.held.fulfill({contentType:'video/webm', body:bytes});
  await page.getByRole('button',{name:task[older]}).click();
  await expect(panel.getByText('Your newer review stays open.',{exact:false})).toBeVisible();
  await expect(page.locator('.recognition-facts')).toContainText('newer-segment-review');
  expect(state.writes).toEqual([]);
});

for (const hidden of ['workspace', 'page']) test(`leaving the ${hidden} cancels a late backup opening and preserves the loaded review`, async ({page}) => {
  const {state, panel} = await setup(page, 'backup');
  if (hidden === 'workspace') await nav(page,'Events').click();
  else await page.evaluate(() => {Object.defineProperty(document,'hidden',{configurable:true,value:true}); document.dispatchEvent(new Event('visibilitychange'));});
  await expect(panel.getByRole('button',{name:'Cancel backup opening', exact:true})).toHaveCount(0);
  await state.held.fulfill({contentType:'video/webm', body:bytes}).catch(() => {});
  if (hidden === 'workspace') await nav(page,'Recognition').click();
  else await page.evaluate(() => {Object.defineProperty(document,'hidden',{configurable:true,value:false}); document.dispatchEvent(new Event('visibilitychange'));});
  await expect(page.locator('.recognition-facts')).toContainText('retained-review');
  await expect(panel.getByRole('button',{name:'Review backup', exact:true})).toBeEnabled();
  expect(state.writes).toEqual([]);
});

for (const rejected of [false, true]) test(`completed-job discovery cannot supersede a newer ${rejected ? 'rejected' : 'pending'} file choice`, async ({page}) => {
  let sessionReply = null, resultReads = 0;
  await page.route('**/api/analysis/**', route => {
    const path = new URL(route.request().url()).pathname;
    if (path.endsWith('/session')) {sessionReply = route; return;}
    if (path.endsWith('/result')) {resultReads++; return route.fulfill({json:result('older-discovered-review')});}
    if (path.endsWith('/source')) return route.fulfill({contentType:'video/webm', body:bytes});
    return route.fulfill({status:503,json:{error:{message:'Unused generated endpoint.'}}});
  });
  await page.goto('/#recognition');
  await page.evaluate(() => {
    const text = File.prototype.text;
    File.prototype.text = function() {
      if (this.name === 'deferred-newer.json') return new Promise(resolve => {window.finishGeneratedReviewRead = async () => resolve(await text.call(this));});
      return text.call(this);
    };
  });
  await page.getByRole('button',{name:'Connect local analysis',exact:true}).click();
  await expect.poll(() => Boolean(sessionReply)).toBe(true);
  await page.getByRole('button',{name:/^Open saved results/}).click();
  // A chooser opened before controls became disabled can deliver its change
  // after discovery began. Hold File.text so no successful run exists yet.
  await page.getByLabel('Open recognition results').setInputFiles({name:'deferred-newer.json', mimeType:'application/json',
    buffer:Buffer.from(JSON.stringify(rejected ? {} : result('newer-file-review')))});
  await expect(page.locator('#recognition-review-status')).toContainText('Reading recognition results');
  await sessionReply.fulfill({json:{token:'generated-recovery-token', ready:true, recordings:[],
    models:[{id:'model',name:'Generated model'}], rules:[{id:'rules',name:'Generated rules',models:['model'],summary:[]}],
    job:{id,state:'completed',phase:'completed',recording:'generated.webm',frames_read:6,frames_analyzed:2,max_frames:6000,elapsed_seconds:1}}});
  await page.getByRole('button',{name:task.analysis}).click();
  await expect(page.getByRole('region',{name:region.analysis}).locator('.local-analysis-message')).toContainText('A newer review was requested');
  expect(resultReads).toBe(0);
  await page.evaluate(() => window.finishGeneratedReviewRead());
  if (rejected) {
    await expect(page.locator('.recognition-error[role="alert"]')).toBeVisible();
    await expect(page.locator('.recognition-facts')).toHaveCount(0);
  } else await expect(page.locator('.recognition-facts')).toContainText('newer-file-review');
});
